# Try yet another hypothesis: 
# What if filling happens only when BOTH a horizontal AND vertical special pair 
# enclose the cell, but the filling only extends as far as BOTH conditions satisfied?

def solve_and_extend(input_grid):
    """Fill cells where BOTH horiz and vert enclosure, filling extends along BOTH paths"""
    rows = len(input_grid)
    cols = len(input_grid[0])
    special = 0
    fill = 9
    bg = 8

    result = [[input_grid[r][c] for c in range(cols)] for r in range(rows)]

    # Try all pairs of special positions
    for r1 in range(rows):
        for c1 in range(cols):
            if input_grid[r1][c1] != special:
                continue
            for r2 in range(rows):
                for c2 in range(cols):
                    if input_grid[r2][c2] != special:
                        continue

                    # Only consider distinct corners of a rectangle
                    if r1 == r2 or c1 == c2:
                        continue

                    # Define rectangle corners
                    r_min, r_max = min(r1, r2), max(r1, r2)
                    c_min, c_max = min(c1, c2), max(c1, c2)

                    # Cell (r,c) is between if r_min < r < r_max and c_min < c < c_max
                    for r in range(r_min + 1, r_max):
                        for c in range(c_min + 1, c_max):
                            if input_grid[r][c] == bg:
                                result[r][c] = fill

    return result

# Try this on demo first
